package net.minecraft.client;
import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.world.entity.Entity;
public final class Minecraft {public static final Minecraft INSTANCE=new Minecraft();public ClientLevel level;public Entity player;public Object screen,connection=new Object();public boolean active=true,paused;public final Options options=new Options();public static Minecraft getInstance(){return INSTANCE;}public final net.minecraft.client.renderer.GameRenderer gameRenderer=new net.minecraft.client.renderer.GameRenderer();public final net.minecraft.client.gui.Font font=new net.minecraft.client.gui.Font();public boolean hasSingleplayerServer(){return true;}public Object getConnection(){return connection;}public boolean isWindowActive(){return active;}public boolean isPaused(){return paused;}public boolean defer;public final java.util.ArrayDeque<Runnable> queued=new java.util.ArrayDeque<>();public void execute(Runnable r){if(defer)queued.add(r);else r.run();}public void drain(){while(!queued.isEmpty())queued.removeFirst().run();}}
